import Image from "next/image";
import { cn } from "@/lib/utils";

export type PanelTone = "sage" | "cream" | "mist" | "none";

const panelClass: Record<PanelTone, string> = {
  sage: "bg-paper-tint",
  cream: "bg-paper-tint",
  mist: "bg-paper-tint",
  none: "",
};

/**
 * A real screenshot of the app, generated by scripts/screenshots.ts from the
 * demo workspace on a production build. It sits as a crisp sheet on a soft
 * ledger panel, in true color with nothing laid over it.
 * `bleed` lets the sheet run off one side of the panel for a less boxed look.
 */
export function Screenshot({
  name,
  alt,
  caption,
  className,
  priority,
  tone = "none",
  bleed,
  sizes = "(min-width: 1024px) 60vw, 100vw",
  onDark = false,
}: {
  name: string;
  alt: string;
  caption?: string;
  className?: string;
  priority?: boolean;
  tone?: PanelTone;
  bleed?: "right" | "left" | "bottom";
  sizes?: string;
  /** On a dark band: the caption uses the light muted ink. */
  onDark?: boolean;
}) {
  const sheet = (
    <div className="overflow-hidden rounded-lg border border-rule bg-paper shadow-lift">
      <Image src={`/screens/${name}.webp`} alt={alt} width={1440} height={900} sizes={sizes} priority={priority} quality={90} className="block h-auto w-full" />
    </div>
  );
  return (
    <figure className={cn("min-w-0", className)}>
      {tone === "none" ? (
        sheet
      ) : (
        <div
          className={cn(
            "overflow-hidden rounded-lg",
            panelClass[tone],
            bleed === "right" && "py-6 pl-6 sm:py-10 sm:pl-10 lg:py-12 lg:pl-12 [&>div]:-mr-[12%]",
            bleed === "left" && "py-6 pr-6 sm:py-10 sm:pr-10 lg:py-12 lg:pr-12 [&>div]:-ml-[12%]",
            bleed === "bottom" && "px-6 pt-6 sm:px-10 sm:pt-10 lg:px-14 lg:pt-14 [&>div]:-mb-[18%] [&>div]:rounded-b-none",
            !bleed && "p-5 sm:p-10 lg:p-12",
          )}
        >
          {sheet}
        </div>
      )}
      {caption ? <figcaption className={cn("mt-3 text-sm", onDark ? "text-on-ink-muted" : "text-ink-muted")}>{caption}</figcaption> : null}
    </figure>
  );
}
